import { useEffect, useState, useMemo } from "react";
import { API_URL } from "../config";

let cache = null;
let cacheTs = 0;
const CACHE_MS = 60_000;

export function useMapData() {
  const [zones, setZones] = useState(cache?.zones || []);
  const [complaints, setComplaints] = useState(cache?.complaints || []);
  const [loading, setLoading] = useState(!cache);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (cache && Date.now() - cacheTs < CACHE_MS) {
      setLoading(false);
      return;
    }

    let cancelled = false;
    (async () => {
      try {
        const [zonesRes, compRes] = await Promise.all([
          fetch(`${API_URL}/api/zones`),
          fetch(`${API_URL}/public-complaints`),
        ]);
        const z = zonesRes.ok ? await zonesRes.json() : [];
        const c = compRes.ok ? await compRes.json() : [];
        if (cancelled) return;
        cache = { zones: z, complaints: c };
        cacheTs = Date.now();
        setZones(z);
        setComplaints(c);
        setLoading(false);
      } catch (e) {
        if (!cancelled) {
          setError(e);
          setLoading(false);
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, []);

  const normalizedComplaints = useMemo(
    () =>
      complaints
        .filter((c) => {
          const lat = parseFloat(c.latitude);
          const lon = parseFloat(c.longitude);
          return !isNaN(lat) && !isNaN(lon);
        })
        .map((c) => ({
          ...c,
          latitude: parseFloat(c.latitude),
          longitude: parseFloat(c.longitude),
        })),
    [complaints]
  );

  const normalizedZones = useMemo(
    () =>
      zones
        .filter((z) => {
          const lat = parseFloat(z.center_lat);
          const lon = parseFloat(z.center_lon);
          return !isNaN(lat) && !isNaN(lon) && (z.total_issues || 0) > 0;
        })
        .map((z) => ({
          ...z,
          center_lat: parseFloat(z.center_lat),
          center_lon: parseFloat(z.center_lon),
        })),
    [zones]
  );

  return {
    zones: normalizedZones,
    complaints: normalizedComplaints,
    loading,
    error,
  };
}
