import React, { useEffect, useMemo, useRef, useState, useCallback, Suspense } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useSearchParams } from "react-router-dom";
import { useMapData } from "../../hooks/useMapData";
import { loadMapState } from "../../utils/issueNavigation";
import { usePrefersReducedMotion } from "../../utils/performance";

const HotspotMap = React.lazy(() => import("./HotspotMap"));

function buildInsights(zones, complaints) {
  const active = complaints.filter((c) => c.status !== "Resolved");
  const resolved = complaints.filter((c) => c.status === "Resolved");
  const road = complaints.filter((c) =>
    /road|pothole|street|footpath/i.test(c.category || "")
  );
  const water = complaints.filter((c) => /water|drain|sewage/i.test(c.category || ""));
  const topZone = [...zones].sort((a, b) => (b.total_issues || 0) - (a.total_issues || 0))[0];
  const bangalore = zones.find((z) =>
    /bangalore|bengaluru/i.test(z.zone_name || z.name || "")
  );

  const pick = (arr) => arr.find((c) => c.latitude && c.longitude);

  return [
    {
      id: "live",
      title: "Live civic intelligence",
      body: `${active.length} active public reports mapped across India right now.`,
      stat: `${complaints.length} total`,
      fly: topZone
        ? { lat: topZone.center_lat, lng: topZone.center_lon, zoom: 11 }
        : { lat: 12.9716, lng: 77.5946, zoom: 11 },
    },
    {
      id: "roads",
      title: "Road & infrastructure hotspots",
      body: `${road.length} road-related issues — zoom in to inspect pin-level detail.`,
      stat: road.length ? "High activity" : "Monitoring",
      fly: pick(road)
        ? { lat: pick(road).latitude, lng: pick(road).longitude, zoom: 15 }
        : topZone
          ? { lat: topZone.center_lat, lng: topZone.center_lon, zoom: 12 }
          : null,
    },
    {
      id: "water",
      title: "Water & sanitation pulse",
      body: `Track ${water.length} water and drainage reports affecting neighbourhoods.`,
      stat: `${Math.round((resolved.length / Math.max(complaints.length, 1)) * 100)}% resolved overall`,
      fly: pick(water)
        ? { lat: pick(water).latitude, lng: pick(water).longitude, zoom: 14 }
        : null,
    },
    {
      id: "city",
      title: "Top civic zones this week",
      body: bangalore
        ? `${bangalore.zone_name || "Bengaluru"} zone: ${bangalore.total_issues || 0} clustered reports.`
        : topZone
          ? `Densest zone: ${topZone.total_issues || 0} issues — tap markers to open any report.`
          : "Pan India view — scroll to explore regional hotspots.",
      stat: "Tap any pin",
      fly: bangalore
        ? { lat: bangalore.center_lat, lng: bangalore.center_lon, zoom: 13 }
        : topZone
          ? { lat: topZone.center_lat, lng: topZone.center_lon, zoom: 12 }
          : null,
    },
  ].filter((i) => i.fly);
}

function ScrollMapExperience() {
  const { zones, complaints, loading } = useMapData();
  const [searchParams] = useSearchParams();
  const reducedMotion = usePrefersReducedMotion();
  const sectionRef = useRef(null);
  const [progress, setProgress] = useState(0);
  const [mapState, setMapState] = useState(() => loadMapState());

  const insights = useMemo(() => buildInsights(zones, complaints), [zones, complaints]);

  const insightIndex = Math.min(
    Math.floor(progress * insights.length),
    Math.max(insights.length - 1, 0)
  );
  const current = insights[insightIndex] || insights[0];

  const selectedIssueId =
    searchParams.get("issue") || mapState?.issueId || null;

  const updateProgress = useCallback(() => {
    const el = sectionRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const scrollable = el.offsetHeight - window.innerHeight;
    if (scrollable <= 0) return;
    const scrolled = Math.min(Math.max(-rect.top, 0), scrollable);
    setProgress(scrolled / scrollable);
  }, []);

  useEffect(() => {
    updateProgress();
    window.addEventListener("scroll", updateProgress, { passive: true });
    window.addEventListener("resize", updateProgress, { passive: true });
    return () => {
      window.removeEventListener("scroll", updateProgress);
      window.removeEventListener("resize", updateProgress);
    };
  }, [updateProgress]);

  useEffect(() => {
    const lat = searchParams.get("lat");
    const lng = searchParams.get("lng");
    const zoom = searchParams.get("zoom");
    if (lat && lng) {
      setMapState((s) => ({
        ...s,
        lat: parseFloat(lat),
        lng: parseFloat(lng),
        zoom: zoom ? parseFloat(zoom) : 13,
      }));
    }
  }, [searchParams]);

  const flyTarget = useMemo(() => {
    if (current?.fly) return current.fly;
    if (mapState?.lat != null) {
      return { lat: mapState.lat, lng: mapState.lng, zoom: mapState.zoom || 13 };
    }
    return null;
  }, [current, mapState]);

  const scrollHeight = reducedMotion ? "auto" : `${Math.max(insights.length, 3) * 100}vh`;

  return (
    <section
      ref={sectionRef}
      id="civic-map-scroll"
      className="relative bg-[#0a0a0a]"
      style={{ minHeight: scrollHeight }}
    >
      <div className="sticky top-[4.5rem] h-[calc(100vh-4.5rem)] w-full overflow-hidden">
        <Suspense
          fallback={
            <div className="absolute inset-0 bg-[#0a0a0a] flex items-center justify-center">
              <div className="h-10 w-10 rounded-full border-2 border-indigo-400 border-t-transparent animate-spin" />
            </div>
          }
        >
          <HotspotMap
            variant="scroll"
            zones={zones}
            complaints={complaints}
            loading={loading}
            flyTarget={flyTarget}
            selectedIssueId={selectedIssueId}
            onMapMove={(s) => setMapState((prev) => ({ ...prev, ...s }))}
          />
        </Suspense>

        {/* Insight overlay */}
        <div className="absolute bottom-0 left-0 right-0 z-[700] pointer-events-none p-4 md:p-8">
          <div className="max-w-2xl pointer-events-auto">
            <AnimatePresence mode="wait">
              <motion.div
                key={current?.id}
                initial={{ opacity: 0, y: 24 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -16 }}
                transition={{ duration: 0.45, ease: [0.25, 0.1, 0.25, 1] }}
                className="rounded-2xl border border-white/10 bg-black/55 backdrop-blur-xl px-6 py-5 shadow-2xl"
              >
                <p className="text-[#FFD166] text-xs font-bold uppercase tracking-widest mb-1">
                  {current?.stat}
                </p>
                <h2 className="text-white text-xl md:text-2xl font-bold mb-2">
                  {current?.title}
                </h2>
                <p className="text-gray-300 text-sm md:text-base leading-relaxed">
                  {current?.body}
                </p>
                <div className="flex gap-1.5 mt-4">
                  {insights.map((_, i) => (
                    <span
                      key={i}
                      className={`h-1 flex-1 rounded-full transition-colors duration-300 ${
                        i === insightIndex ? "bg-indigo-400" : "bg-white/20"
                      }`}
                    />
                  ))}
                </div>
              </motion.div>
            </AnimatePresence>
          </div>
        </div>

        <div
          className="absolute inset-x-0 top-0 h-32 bg-gradient-to-b from-[#0a0a0a] to-transparent pointer-events-none z-[600]"
          aria-hidden
        />
      </div>

      {/* Scroll spacer panels (accessibility / reduced motion) */}
      {!reducedMotion &&
        insights.map((ins, i) => (
          <div
            key={ins.id}
            className="h-screen flex items-end justify-center pb-32 pointer-events-none opacity-0"
            aria-hidden={i !== insightIndex}
          >
            <span className="sr-only">{ins.title}</span>
          </div>
        ))}
    </section>
  );
}

export default ScrollMapExperience;
